\set ON_ERROR_STOP on
begin;
delete from public.aitask_entities where workspace_id='aitask-main' and entity_type not in ('custom_role','task_status');
update aitask_entities set data = data || '{"currency":"MYR","revision":1}' where workspace_id='aitask-main' and entity_type='client_plan';
update aitask_entities set data = data || '{"addonSnapshots":[],"currency":"MYR","planRevision":1,"pricingSnapshotId":""}' where workspace_id='aitask-main' and entity_type='service_cycle';
update aitask_entities set data = data || '{"milestones":[],"requireClearClosureChecklist":false}' where workspace_id='aitask-main' and entity_type='project';
update aitask_entities set data = data || '{"assignedAt":"2026-11-02T00:00:00.000Z","clientApprovalStatus":"Pending","dueReminderSent":false,"generatedFromDeliverable":false,"isRecurring":false,"predecessorTaskIds":[],"recurrenceFrequency":"none","assignmentState":"assigned_staff"}' where workspace_id='aitask-main' and entity_type='task';
update public.aitask_workspaces set version=version+1 where id='aitask-main';
commit;
